     function ConsentField({ inputId, helpId, errorId }) {
       const checkbox = createElement("input", {
         id: inputId,
         name: "consent",
         type: "checkbox",
         required: true,
         "aria-describedby": helpId
       });

       const label = createElement(
         "label",
         { className: "checkbox-label", htmlFor: inputId },
         "I agree to the terms of use",
         createElement("span", { className: "required-mark", "aria-hidden": "true" }, "*"),
         createElement("span", { className: "sr-only" }, " required")
       );

       const helpText = createElement("p", {
         id: helpId,
         className: "helper-text",
         text: "Required to continue."
       });

       const errorText = createElement("p", {
         id: errorId,
         className: "error-text",
         hidden: true,
         text: "Error: Agree to the terms of use before submitting."
       });

       return createElement(
