         inputId: "consent-checkbox",
         helpId: "consent-help",
         errorId: "consent-error"
       });

       const checkbox = field.querySelector('input[type="checkbox"]');
       const errorText = field.querySelector("#consent-error");
       const status = createElement("p", {
         className: "status-text",
         id: "form-status",
         role: "status",
         "aria-live": "polite"
       });

